"""Scripted OpenAI-compatible mock. Responses are scripted, NOT generated by any LLM."""

import json
from typing import Optional

import httpx

from hive_exec.llm.providers import ProviderRow, load_store
from hive_exec.llm.router import Router
from hive_exec.planner.llm import LLMPlanner

MOCK_MODEL = "hive-mock/scripted-qwen"  # never labeled as live Qwen3-8B
MOCK_ID = "scripted-mock"
MOCK_HOST = "mock.invalid"

REJECT = json.dumps({"schema_version": "hive.plan-proposal.v1", "disposition": "reject", "scope": None,
                     "summary": "No flight skill.", "mission_goals": [], "stage_goals": [], "tasks": [],
                     "issues": [], "clarification_question": None})


class ScriptedQwen:
    """OpenAI-compatible mock for tests. Responses are scripted, NOT generated by Qwen."""

    def __init__(self, contents: list[str], model: str = MOCK_MODEL):
        self.contents = list(contents)
        self.model = model
        self.requests: list[dict] = []

    def handler(self, request: httpx.Request) -> httpx.Response:
        if request.url.path.endswith("/models"):
            return httpx.Response(200, json={"data": [{"id": self.model}]})
        body = json.loads(request.content)
        self.requests.append(body)
        last = body["messages"][-1]["content"]
        if "Fly the drone to the roof" in last:  # probe schema round trip
            content = REJECT
        elif last == "reply with: ok":  # probe ping
            content = "ok"
        else:
            content = self.contents.pop(0)
        return httpx.Response(200, json={"model": self.model, "choices": [
            {"message": {"role": "assistant", "content": content}, "finish_reason": "stop"}],
            "usage": {"prompt_tokens": 100, "completion_tokens": 50}})


def mock_row(pid: str = MOCK_ID, host: str = MOCK_HOST, **over) -> ProviderRow:
    fields = dict(id=pid, label="Scripted mock (not an LLM)", kind="openai_compatible",
                  base_url=f"http://{host}/v1", model=MOCK_MODEL, structured_mode="structured_outputs")
    fields.update(over)
    return ProviderRow(**fields)


def save_chain(rows: list, keys: Optional[dict] = None, role: str = "executive") -> None:
    """Write rows + the role chain to the test's temp store (HIVE_PROVIDERS_FILE)."""
    store = load_store()
    for row in rows:
        store.upsert(row, api_key=(keys or {}).get(row.id))
    store.set_role(role, [row.id for row in rows])
    store.save()


def scripted_planner(contents: list[str]) -> tuple[LLMPlanner, ScriptedQwen]:
    mock = ScriptedQwen(contents)
    save_chain([mock_row()])
    planner = LLMPlanner(Router(transport=httpx.MockTransport(mock.handler)))
    return planner, mock
